styleBlocks.css:
.biology-score-unavailable-group > summary {
  cursor: pointer;
  padding: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--border) 65%, transparent);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--bg-secondary) 35%, transparent);
  color: var(--text-secondary);
  font-size: 13px;
  font-weight: 700;
  list-style: none;
}

.dashboard-lab-date-range {
  display: flex; align-items: center; justify-content: space-between;
  flex-wrap: wrap; gap: 12px; margin-bottom: 20px; padding: 12px 16px;
  border: 1px solid var(--border); border-radius: var(--radius-sm);
  background: var(--bg-secondary); color: var(--text-primary);
}

.dashboard-lab-date-range p {
  margin: 4px 0 0; font-size: 12px; line-height: 1.5; color: var(--text-secondary);
}
